package pk.saleprofit.urdu;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;import android.text.InputType;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity {
 int green=0xFF087F68, dark=0xFF075B4A, pale=0xFFE8F5F1; DB db; LinearLayout page,body; String screen="home"; ArrayList<Line> lines=new ArrayList<>(); Spinner shopSpinner; EditText[] qtys,prices; TextView totalView; int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} 
 static class Line {int id,qty;String name;double cost,price;Line(int i,String n,double c,double p){id=i;name=n;cost=c;price=p;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(dark);getWindow().setNavigationBarColor(dark);db=new DB(this);showHome();}
 TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xFF17352F);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(dp(8),dp(7),dp(8),dp(7));return t;}
 Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(0xFFFFFFFF);b.setAllCaps(false);b.setTextSize(14);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(green));b.setOnClickListener(v->r.run());return b;}
 EditText edit(String s,boolean number){EditText e=new EditText(this);e.setSingleLine(true);e.setText(s);e.setTextSize(15);e.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);e.setPadding(dp(8),dp(3),dp(8),dp(3));if(number)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);return e;}
 void base(String title){screen=title;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xFFF5F8F7);TextView head=text("سیلز اور منافع  |  "+title,21,true);head.setTextColor(-1);head.setBackgroundColor(dark);head.setPadding(dp(16),dp(16),dp(16),dp(16));root.addView(head);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setPadding(dp(12),dp(10),dp(12),dp(16));body.setOrientation(LinearLayout.VERTICAL);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));HorizontalScrollView hs=new HorizontalScrollView(this);LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(0xFFFFFFFF);String[][] n={{"ہوم","home"},{"نئی سیل","sale"},{"دکانیں","shops"},{"آئٹمز","items"},{"رپورٹ","reports"},{"سیٹنگز","settings"}};for(String[] a:n){Button x=new Button(this);x.setText(a[0]);x.setAllCaps(false);x.setTextSize(12);x.setOnClickListener(v->navigate(a[1]));nav.addView(x);}hs.addView(nav);root.addView(hs);setContentView(root);}
 void navigate(String s){switch(s){case"home":showHome();break;case"sale":showSale();break;case"shops":showShops();break;case"items":showItems();break;case"reports":showReports();break;default:showSettings();}}
 void card(String title,String value){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(12),dp(8),dp(12),dp(8));c.setBackgroundTintList(null);c.setBackgroundColor(-1);c.addView(text(title,14,false));c.addView(text(value,23,true));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(c,p);}
 void showHome(){base("ہوم");double[] s=db.summary("date(created)=date('now','localtime')");card("آج کی کل سیل",money(s[0])+" روپے");card("آج کا منافع",money(s[1])+" روپے");card("کل دکانیں",String.valueOf(db.count("shops")));card("کل آئٹمز",String.valueOf(db.count("items")));body.addView(btn("＋ نئی سیل درج کریں",()->showSale()));body.addView(text("حالیہ سیلز",18,true));Cursor c=db.getReadableDatabase().rawQuery("SELECT date(s.created),sh.name,SUM(s.total),SUM(s.profit) FROM sales s JOIN shops sh ON sh.id=s.shop_id GROUP BY date(s.created),s.shop_id ORDER BY s.created DESC LIMIT 20",null);while(c.moveToNext())body.addView(text(c.getString(1)+"  •  "+c.getString(0)+"\nسیل: "+money(c.getDouble(2))+"  |  منافع: "+money(c.getDouble(3)),15,false));c.close();}
 void showSale(){base("نئی سیل");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM shops ORDER BY name",null);ArrayList<String> names=new ArrayList<>();ArrayList<Integer> ids=new ArrayList<>();while(c.moveToNext()){ids.add(c.getInt(0));names.add(c.getString(1));}c.close();if(names.isEmpty()){body.addView(text("پہلے دکان شامل کریں",17,true));return;}shopSpinner=new Spinner(this);shopSpinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));body.addView(text("دکان منتخب کریں",16,true));body.addView(shopSpinner);Cursor it=db.getReadableDatabase().rawQuery("SELECT id,name,cost,price FROM items ORDER BY name",null);ArrayList<Line> products=new ArrayList<>();while(it.moveToNext())products.add(new Line(it.getInt(0),it.getString(1),it.getDouble(2),it.getDouble(3)));it.close();lines=products;qtys=new EditText[lines.size()];prices=new EditText[lines.size()];for(int i=0;i<lines.size();i++){Line l=lines.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(4),0,dp(4));row.setBackgroundColor(-1);TextView nm=text(l.name,14,true);row.addView(nm,new LinearLayout.LayoutParams(0,-2,2));LinearLayout q=new LinearLayout(this);Button minus=new Button(this);minus.setText("−");qtys[i]=edit("0",true);qtys[i].setGravity(Gravity.CENTER);qtys[i].setInputType(InputType.TYPE_CLASS_NUMBER);final int ix=i;minus.setOnClickListener(v->{int x=val(qtys[ix]);qtys[ix].setText(""+Math.max(0,x-1));});Button plus=new Button(this);plus.setText("+");plus.setOnClickListener(v->{int x=val(qtys[ix]);qtys[ix].setText(""+(x+1));});q.addView(minus);q.addView(qtys[i],new LinearLayout.LayoutParams(dp(42),dp(48)));q.addView(plus);row.addView(q);prices[i]=edit(money(l.price),true);prices[i].setHint("قیمت");row.addView(prices[i],new LinearLayout.LayoutParams(dp(76),dp(48)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(4);body.addView(row,rp);View line=new View(this);line.setBackgroundColor(0xFFE0E8E5);body.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}body.addView(text("قیمت دکاندار کے مطابق تبدیل کر سکتے ہیں۔ خرید قیمت اسکرین پر نہیں دکھائی جاتی۔",13,false));body.addView(btn("سیل محفوظ کریں",()->saveSale(ids)));}
 int val(EditText e){try{return Integer.parseInt(e.getText().toString().trim());}catch(Exception ex){return 0;}}
 void saveSale(ArrayList<Integer> ids){int shop=ids.get(shopSpinner.getSelectedItemPosition());ArrayList<Line> chosen=new ArrayList<>();double total=0,profit=0;for(int i=0;i<lines.size();i++){int q=val(qtys[i]);if(q<=0)continue;double p;try{p=Double.parseDouble(prices[i].getText().toString().replace(",","").trim());}catch(Exception e){p=lines.get(i).price;}Line l=lines.get(i);l.qty=q;l.price=p;chosen.add(l);total+=q*p;profit+=q*(p-l.cost);}if(chosen.isEmpty()){toast("کم از کم ایک آئٹم کی مقدار درج کریں");return;}SQLiteDatabase w=db.getWritableDatabase();ContentValues cv=new ContentValues();cv.put("shop_id",shop);cv.put("created",new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).format(new Date()));cv.put("total",total);cv.put("profit",profit);long sid=w.insert("sales",null,cv);for(Line l:chosen){ContentValues v=new ContentValues();v.put("sale_id",sid);v.put("item_id",l.id);v.put("qty",l.qty);v.put("price",l.price);v.put("cost",l.cost);v.put("profit",l.qty*(l.price-l.cost));w.insert("sale_lines",null,v);}toast("سیل محفوظ ہو گئی");showHome();}
 void showShops(){base("دکانیں");EditText name=edit("",false);name.setHint("نئی دکان کا نام");body.addView(name);body.addView(btn("دکان شامل کریں",()->{String n=name.getText().toString().trim();if(!n.isEmpty()){ContentValues v=new ContentValues();v.put("name",n);db.getWritableDatabase().insert("shops",null,v);showShops();}}));Cursor c=db.getReadableDatabase().rawQuery("SELECT sh.id,sh.name,COALESCE(SUM(s.total),0),COALESCE(SUM(s.profit),0) FROM shops sh LEFT JOIN sales s ON s.shop_id=sh.id GROUP BY sh.id ORDER BY sh.name",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setBackgroundColor(-1);row.addView(text(c.getString(1),16,true));row.addView(text("کل سیل: "+money(c.getDouble(2))+" روپے   •   پرافٹ: "+money(c.getDouble(3))+" روپے",14,false));row.addView(btn("دکان حذف کریں",()->new AlertDialog.Builder(this).setMessage("کیا یہ دکان حذف کرنی ہے؟ اس کی سیلز بھی حذف ہوں گی۔").setNegativeButton("نہیں",null).setPositiveButton("ہاں، حذف",(d,w)->{db.deleteShop(id);showShops();}).show()));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(row,p);}c.close();}
 void showItems(){base("آئٹمز");EditText name=edit("",false);name.setHint("آئٹم کا نام");EditText cost=edit("",true);cost.setHint("خرید قیمت (صرف انتظام کے لیے)");EditText price=edit("",true);price.setHint("فروخت قیمت");body.addView(name);body.addView(cost);body.addView(price);body.addView(btn("آئٹم شامل کریں",()->{String n=name.getText().toString().trim();try{if(n.isEmpty())throw new Exception();ContentValues v=new ContentValues();v.put("name",n);v.put("cost",Double.parseDouble(cost.getText().toString()));v.put("price",Double.parseDouble(price.getText().toString()));db.getWritableDatabase().insert("items",null,v);showItems();}catch(Exception e){toast("نام، خرید اور فروخت قیمت درج کریں");}}));Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,cost,price FROM items ORDER BY name",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout r=new LinearLayout(this);r.setBackgroundColor(-1);r.setOrientation(1);r.addView(text(c.getString(1),16,true));r.addView(btn("ترمیم",()->editItem(id)));r.addView(btn("حذف",()->new AlertDialog.Builder(this).setMessage("آئٹم حذف کریں؟").setNegativeButton("نہیں",null).setPositiveButton("حذف",(d,w)->{db.getWritableDatabase().delete("items","id=?",new String[]{""+id});showItems();}).show()));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(7);body.addView(r,p);}c.close();}
 void editItem(int id){Cursor c=db.getReadableDatabase().rawQuery("SELECT name,cost,price FROM items WHERE id="+id,null);if(!c.moveToFirst()){c.close();return;}EditText n=edit(c.getString(0),false),co=edit(money(c.getDouble(1)),true),pr=edit(money(c.getDouble(2)),true);c.close();LinearLayout box=new LinearLayout(this);box.setPadding(dp(12),0,dp(12),0);box.setOrientation(1);box.addView(n);box.addView(co);box.addView(pr);new AlertDialog.Builder(this).setTitle("آئٹم میں ترمیم").setView(box).setNegativeButton("منسوخ",null).setPositiveButton("محفوظ",(d,w)->{try{ContentValues v=new ContentValues();v.put("name",n.getText().toString());v.put("cost",Double.parseDouble(co.getText().toString()));v.put("price",Double.parseDouble(pr.getText().toString()));db.getWritableDatabase().update("items",v,"id=?",new String[]{""+id});showItems();}catch(Exception e){toast("درست قیمت درج کریں");}}).show();}
 void showReports(){base("رپورٹس");String[] periods={"آج","اس ہفتے","اس مہینے","اس سال"};String[] expr={"date(created)=date('now','localtime')","created>=date('now','-6 days','localtime')","strftime('%Y-%m',created)=strftime('%Y-%m','now','localtime')","strftime('%Y',created)=strftime('%Y','now','localtime')"};for(int i=0;i<periods.length;i++){Cursor c=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(total),0),COALESCE(SUM(profit),0),COUNT(*) FROM sales WHERE "+expr[i],null);c.moveToFirst();card(periods[i]+" کی رپورٹ","سیل "+money(c.getDouble(0))+" روپے\nمنافع "+money(c.getDouble(1))+" روپے\nآرڈر "+c.getInt(2));c.close();}body.addView(text("دکان وار ماہانہ/سالانہ حساب سیلز کی تاریخ کے مطابق محفوظ ہے۔",14,false));}
 void showSettings(){base("سیٹنگز");body.addView(text("ڈیٹا اسی موبائل میں محفوظ ہوتا ہے اور بنیادی کام کے لیے انٹرنیٹ ضروری نہیں۔",16,false));body.addView(btn("ڈیٹا کا خلاصہ",()->new AlertDialog.Builder(this).setMessage("دکانیں: "+db.count("shops")+"\nآئٹمز: "+db.count("items")+"\nسیلز: "+db.count("sales")).setPositiveButton("ٹھیک ہے",null).show()));body.addView(text("اہم: ایپ حذف کرنے سے پہلے فون کی ایپ ڈیٹا سیٹنگز میں بیک اپ دستیاب ہو تو محفوظ کریں۔ اگلے مرحلے میں فائل ایکسپورٹ/امپورٹ شامل کیا جانا چاہیے۔",14,false));}
 String money(double d){return String.format(Locale.US,"%.0f",d);}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 class DB extends SQLiteOpenHelper{DB(Context c){super(c,"sales_profit_urdu.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE shops(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL)");d.execSQL("CREATE TABLE items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,cost REAL NOT NULL,price REAL NOT NULL)");d.execSQL("CREATE TABLE sales(id INTEGER PRIMARY KEY AUTOINCREMENT,shop_id INTEGER,created TEXT,total REAL,profit REAL)");d.execSQL("CREATE TABLE sale_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,sale_id INTEGER,item_id INTEGER,qty INTEGER,price REAL,cost REAL,profit REAL)");String[] ss=SHOPS;for(String s:ss){ContentValues v=new ContentValues();v.put("name",s);d.insert("shops",null,v);}Object[][] its=ITEMS;for(Object[] a:its){ContentValues v=new ContentValues();v.put("name",(String)a[0]);v.put("cost",(Integer)a[1]);v.put("price",(Integer)a[2]);d.insert("items",null,v);}}public void onUpgrade(SQLiteDatabase d,int a,int b){}int count(String t){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM "+t,null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}double[] summary(String where){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(total),0),COALESCE(SUM(profit),0) FROM sales WHERE "+where,null);c.moveToFirst();double[] a={c.getDouble(0),c.getDouble(1)};c.close();return a;}void deleteShop(int id){SQLiteDatabase w=getWritableDatabase();Cursor c=w.rawQuery("SELECT id FROM sales WHERE shop_id="+id,null);ArrayList<String> a=new ArrayList<>();while(c.moveToNext())a.add(c.getString(0));c.close();for(String sid:a)w.delete("sale_lines","sale_id=?",new String[]{sid});w.delete("sales","shop_id=?",new String[]{""+id});w.delete("shops","id=?",new String[]{""+id});}}
 static final String[] SHOPS = {"شہباز کریانہ سٹور", "ماسٹر کریانہ سٹور", "اعوان کریانہ سٹور", "گل نواز کریانہ سٹور", "نصر کریانہ سٹور", "برہان کریانہ سٹور", "عبد الرحمن کریانہ", "مہر کریانہ سٹور", "حرمین کریانہ سٹور", "ہادی کریانہ سٹور", "آصف کریانہ سٹور", "بلال کریانہ سٹور", "ملک کریانہ سٹور", "فرحت کریانہ سٹور", "العباس کریانہ سٹور", "الرحمن کریانہ سٹور", "حافظ ریحان کریانہ", "فیض کریانہ", "علی ڈسکاؤنٹ شاپ", "ظہور کریانہ", "علی سپر سٹور", "بابا کریانہ", "ظہور آگے کریانہ", "عطاء اللہ کریانہ", "نیو حافظ کریانہ", "ندیم کریانہ", "مہر زیشان کریانہ", "عبداللہ کریانہ", "اشرف کریانہ", "شیخ اسلم کریانہ", "ہادی پورہ کریانہ", "786 کریانہ"};
 static final Object[][] ITEMS = {new Object[]{"گرین نمکو 20 روپے والی",280,300}, new Object[]{"پاپڑ پیکٹ",90,100}, new Object[]{"پاپڑ بنڈل",550,590}, new Object[]{"ملائی بوٹی چھوٹی پیکٹ",87,100}, new Object[]{"ملائی بوٹی چھوٹی بنڈل",520,570}, new Object[]{"ملائی بوٹی بڑی پیکٹ",168,200}, new Object[]{"چنا پکوڑا پیکٹ",168,190}, new Object[]{"چنا پکوڑا بنڈل",1020,1150}, new Object[]{"گرین نمکو پچاس والی",750,790}, new Object[]{"پیزا جیلی پانچ والی",120,130}, new Object[]{"پیزا جیلی دس والی",170,180}, new Object[]{"جزٹ جیلی پانچ والی",120,130}, new Object[]{"جزٹ جیلی دس والی",150,160}, new Object[]{"پانچ والی جیلی",120,130}, new Object[]{"فروٹ گالا",160,170}};
}